var pl;
(function( pl ) {

	// Walk a list term; returns the elements and the term that ends the list.
	var walk = function( list ) {
		var items = [];
		var pointer = list;
		while( pl.type.is_term( pointer ) && pointer.indicator === "./2" ) {
			items.push( pointer.args[0] );
			pointer = pointer.args[1];
		}
		return { items: items, tail: pointer };
	};

	// Build a list term from an array.
	var build = function( items ) {
		var list = new pl.type.Term( "[]", [] );
		for( var i = items.length - 1; i >= 0; i-- )
			list = new pl.type.Term( ".", [items[i], list] );
		return list;
	};

	// Read a proper list into an array. Throws the matching error and returns null otherwise.
	var read = function( thread, atom, list ) {
		var walked = walk( list );
		if( pl.type.is_variable( walked.tail ) ) {
			thread.throw_error( pl.error.instantiation( atom.indicator ) );
			return null;
		}
		if( !pl.type.is_term( walked.tail ) || walked.tail.indicator !== "[]/0" ) {
			thread.throw_error( pl.error.type( "list", list, atom.indicator ) );
			return null;
		}
		return walked.items;
	};

	// Sort into standard order and drop repeated elements.
	var normalize = function( items ) {
		var sorted = items.slice().sort( pl.compare );
		var set = [];
		for( var i = 0; i < sorted.length; i++ ) {
			if( set.length === 0 || pl.compare( set[set.length - 1], sorted[i] ) !== 0 )
				set.push( sorted[i] );
		}
		return set;
	};

	// Merge two ordered sets into one ordered set.
	var union = function( a, b ) {
		var out = [], i = 0, j = 0;
		while( i < a.length && j < b.length ) {
			var order = pl.compare( a[i], b[j] );
			if( order < 0 ) out.push( a[i++] );
			else if( order > 0 ) out.push( b[j++] );
			else { out.push( a[i] ); i++; j++; }
		}
		while( i < a.length ) out.push( a[i++] );
		while( j < b.length ) out.push( b[j++] );
		return out;
	};

	// The elements of the first ordered set that the second one lacks.
	var subtract = function( a, b ) {
		var out = [], i = 0, j = 0;
		while( i < a.length && j < b.length ) {
			var order = pl.compare( a[i], b[j] );
			if( order < 0 ) out.push( a[i++] );
			else if( order > 0 ) j++;
			else { i++; j++; }
		}
		for( ; i < a.length; i++ ) out.push( a[i] );
		return out;
	};

	// The elements that both ordered sets hold.
	var intersection = function( a, b ) {
		var out = [], i = 0, j = 0;
		while( i < a.length && j < b.length ) {
			var order = pl.compare( a[i], b[j] );
			if( order < 0 ) i++;
			else if( order > 0 ) j++;
			else { out.push( a[i++] ); j++; }
		}
		return out;
	};

	// Binary search in an ordered set.
	// The window [low, high] holds every index that can still match.
	// Each step compares the middle element and drops half of the window.
	// The search ends when the window is empty.
	// Elements are compared in standard order, like the sort that built the set.
	var contains = function( set, elem ) {
		var low = 0, high = set.length - 1;
		while( low <= high ) {
			var mid = ( low + high ) >> 1;
			var order = pl.compare( set[mid], elem );
			if( order === 0 ) return true;
			if( order < 0 ) low = mid + 1;
			else high = mid - 1;
		}
		return false;
	};

	// True when every element of the first ordered set is in the second one.
	var subset = function( a, b ) {
		if( a.length > b.length ) return false;
		var j = 0;
		for( var i = 0; i < a.length; i++ ) {
			while( j < b.length && pl.compare( b[j], a[i] ) < 0 ) j++;
			if( j === b.length || pl.compare( b[j], a[i] ) !== 0 ) return false;
			j++;
		}
		return true;
	};

	// Insert an element at its place in an ordered set.
	var add = function( set, elem ) {
		var i = 0;
		while( i < set.length && pl.compare( set[i], elem ) < 0 ) i++;
		if( i < set.length && pl.compare( set[i], elem ) === 0 ) return set;
		return set.slice( 0, i ).concat( [elem], set.slice( i ) );
	};

	// Remove an element from an ordered set.
	// Elements are compared in standard order, so only a term that is
	// identical to the argument is removed. The result keeps the order
	// of the input and shares its element terms. A missing element
	// leaves the set as it was.
	var del = function( set, elem ) {
		var out = [];
		for( var i = 0; i < set.length; i++ ) {
			if( pl.compare( set[i], elem ) !== 0 ) out.push( set[i] );
		}
		return out;
	};

	var predicates = function() {

		// Unify a computed result with the output argument.
		var give = function( thread, point, result, expected ) {
			thread.prepend( [new pl.type.State( point.goal.replace( new pl.type.Term( "=", [result, expected] ) ), point.substitution, point )] );
		};

		// Succeed without binding anything.
		var succeed = function( thread, point ) {
			thread.prepend( [new pl.type.State( point.goal.replace( null ), point.substitution, point )] );
		};

		// A predicate Set1, Set2, Result built from a set operation.
		var binary = function( operation ) {
			return function( thread, point, atom ) {
				var a = read( thread, atom, atom.args[0] );
				if( a === null ) return;
				var b = read( thread, atom, atom.args[1] );
				if( b === null ) return;
				give( thread, point, build( operation( a, b ) ), atom.args[2] );
			};
		};

		// A predicate Set, Element, Result built from an element operation.
		var element = function( operation ) {
			return function( thread, point, atom ) {
				var set = read( thread, atom, atom.args[0] );
				if( set === null ) return;
				give( thread, point, build( operation( set, atom.args[1] ) ), atom.args[2] );
			};
		};

		return {

			// list_to_ord_set/2
			"list_to_ord_set/2": function( thread, point, atom ) {
				var items = read( thread, atom, atom.args[0] );
				if( items === null ) return;
				give( thread, point, build( normalize( items ) ), atom.args[1] );
			},

			// ord_union/3
			"ord_union/3": binary( union ),

			// ord_subtract/3
			"ord_subtract/3": binary( subtract ),

			// ord_intersection/3
			"ord_intersection/3": binary( intersection ),

			// ord_add_element/3
			"ord_add_element/3": element( add ),

			// ord_del_element/3
			"ord_del_element/3": element( del ),

			// ord_memberchk/2
			"ord_memberchk/2": function( thread, point, atom ) {
				var set = read( thread, atom, atom.args[1] );
				if( set === null ) return;
				if( contains( set, atom.args[0] ) ) succeed( thread, point );
			},

			// ord_subset/2
			"ord_subset/2": function( thread, point, atom ) {
				var a = read( thread, atom, atom.args[0] );
				if( a === null ) return;
				var b = read( thread, atom, atom.args[1] );
				if( b === null ) return;
				if( subset( a, b ) ) succeed( thread, point );
			}

		};
	};

	var exports = ["list_to_ord_set/2", "ord_union/3", "ord_subtract/3", "ord_intersection/3", "ord_add_element/3", "ord_del_element/3", "ord_memberchk/2", "ord_subset/2"];

	if( typeof module !== 'undefined' ) {
		module.exports = function( p ) {
			pl = p;
			new pl.type.Module( "sets", predicates(), exports );
		};
	} else {
		new pl.type.Module( "sets", predicates(), exports );
	}

})( pl );
